using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitDirectiveRetryTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void PhysicalKnownFailureAllowsImmutableOriginalCopyAndSameRestoredFuture(int index){var s=Away();var root=FailedOriginal(s,true,index);HomeUnits(s);var initial=s.DiagnosticSnapshot();var message=initial.Messaging.Messages.Single(m=>m.Id==root.Message);Assert.True(NewGameMilitary.UnitDirectiveRetryAllowed(initial,root.Id));var input=Retry(s,root);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();Assert.Equal(root.Message,copy.Message);Assert.Equal(root.Recipient,copy.Recipient);Assert.NotEqual(root.Attempt,copy.Attempt);Assert.NotEqual(root.Destination,copy.Destination);Assert.Equal(input.DirectiveRetry!.Known.Position,copy.Destination);Assert.Equal(message,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==root.Message));At(s,copy.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,copy.DueAt);var w=s.DiagnosticSnapshot();var r=w.NewMilitary!.UnitDirective!.Receipts.Last();Assert.True(r.Delivered);Assert.True(r.Applied);Assert.Single(w.NewMilitary.UnitDirective.Effects);Assert.False(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));Assert.Equal(root.Id,ContractJson.Read<UnitDirectiveNote>(System.Text.Encoding.UTF8.GetBytes(message.Body)).Request);foreach(var v in new[]{s,restored})At(v,r.ReplyDueAt);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void FailureIsUnavailableUntilTheCourierPhysicallyReportsIt(){var s=Away();var root=FailedOriginal(s,false);Assert.False(NewGameMilitary.UnitDirectiveRetryAllowed(s.DiagnosticSnapshot(),root.Id));var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,root.Attempt,s.PlayerControl.Value));At(s,r.ReplyDueAt);HomeUnits(s);Assert.True(NewGameMilitary.UnitDirectiveRetryAllowed(s.DiagnosticSnapshot(),root.Id));}
 [Fact]public void CopyDoesNotRenewAnOldOriginalsPriorityOverNewHold(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var hold=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(hold,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,d.DueAt);Assert.True(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last().Applied);var oldOrder=s.DiagnosticSnapshot().NewMilitary!.Orders.Last();Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,copy.DueAt);var w=s.DiagnosticSnapshot();Assert.True(w.NewMilitary!.UnitDirective!.Receipts.Last().Delivered);Assert.False(w.NewMilitary.UnitDirective.Receipts.Last().Applied);Assert.Equal(UnitDirectiveOutcome.Superseded,w.NewMilitary.UnitDirective.Effects.Last().Outcome);Assert.Equal(ContractJson.CanonicalHash(oldOrder),ContractJson.CanonicalHash(w.NewMilitary.Orders.Last()));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedCopyReferenceIsRejectedAtomically(int variant){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var input=Retry(s,root);var x=input.DirectiveRetry!;input=variant switch{0=>input with{DirectiveRetry=x with{Contract="unknown"}},1=>input with{DirectiveRetry=x with{Known=x.Known with{Unit=NewGameMilitary.UnitIds[2]}}},2=>input with{DirectiveRetry=x with{Known=x.Known with{Position=new(x.Known.Position.X+1,x.Known.Position.Y)}}},_=>input with{DirectiveRetry=x with{Original=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().Id}}};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void DeadlineCannotBeExtendedByResending(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var input=Retry(s,root);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input with{DeliverBy=s.Seconds+600},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));var until=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==root.Message).DeliverBy!.Value;At(s,until);Assert.False(NewGameMilitary.UnitDirectiveRetryAllowed(s.DiagnosticSnapshot(),root.Id));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Retry(s,root),s.PlayerControl,s.Revision).Code);}
 [Fact]public void RepeatedCopyRequestIsIdempotentAfterPhysicalReceipt(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var input=Retry(s,root);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,0).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Equal(2,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Length);}
 [Fact]public void CopyCannotReplaceTheOriginalDirectivePayload(){var s=Away();var root=FailedOriginal(s);HomeUnits(s);var input=Retry(s,root) with{Directive=Directive(s,1,UnitDirectiveKind.Recall).Directive};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
}
